def rle(s):
    out, cnt, prev = [], 0, ''
    for c in s:
        if c==prev: cnt+=1
        else:
            if prev: out.append(f'{prev}{cnt}')
            prev, cnt = c,1
    out.append(f'{prev}{cnt}')
    return ' '.join(out)
df['rle_text'] = df['text_col'].astype(str).apply(rle)

