from sklearn.model_selection import GridSearchCV
class MultiClassRF:
    def __init__(self):
        self.model = None
        self.grid = None
    def fit(self, X, y):
        param_grid = {'n_estimators': [50, 100], 'max_depth': [4, 8]}
        self.grid = GridSearchCV(RandomForestClassifier(), param_grid, cv=3)
        self.grid.fit(X, y)
        self.model = self.grid.best_estimator_
    def predict(self, X):
        return self.model.predict(X)
X, y = load_digits(return_X_y=True)
clf = MultiClassRF()
clf.fit(X, y)
print('Best params:', clf.grid.best_params_)

