def find_path(start,target,adj):
    stack=[(start,[start])]
    while stack:
        node,path=stack.pop()
        if node==target: return path
        for nbr in adj.get(node,[]):stack.append((nbr,path+[nbr]))
print(find_path('x','a',adj))

